namespace CourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using CourseCatalog.Models;

namespace CourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, creative writing, and rhetoric." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "World history, political history, and historiography." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on CS pedagogy.", IsFeatured = true },
            new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on CS pedagogy.", IsFeatured = false },
            new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases. Covers SQL, normalization, indexing, transaction management, and introduction to NoSQL.", Credits = 3, Schedule = "Mon/Wed 1:00–2:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Prof. David Park", InstructorBio = "Prof. Park spent a decade in industry at major tech companies before joining academia. He specializes in distributed data systems.", IsFeatured = true },
            new() { Id = 4, CourseCode = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", DepartmentId = 1, DepartmentName = "Computer Science", InstructorName = "Dr. Mei Zhang", InstructorBio = "Dr. Zhang is an AI researcher with publications in top ML conferences. She brings cutting-edge research into the classroom.", IsFeatured = false },
            new() { Id = 5, CourseCode = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Robert Williams", InstructorBio = "Dr. Williams is an award-winning educator who has taught calculus for over 20 years.", IsFeatured = true },
            new() { Id = 6, CourseCode = "MATH 202", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations with applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim's research focuses on applied linear algebra and numerical methods.", IsFeatured = false },
            new() { Id = 7, CourseCode = "MATH 340", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", DepartmentId = 2, DepartmentName = "Mathematics", InstructorName = "Dr. Sarah Kim", InstructorBio = "Dr. Kim's research focuses on applied linear algebra and numerical methods.", IsFeatured = false },
            new() { Id = 8, CourseCode = "ENG 101", Title = "College Writing", Description = "Develop clear, effective academic writing skills. Focus on thesis development, argumentation, and research methods.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Prof. James Moore", InstructorBio = "Prof. Moore is a published author and writing coach with expertise in academic and creative non-fiction.", IsFeatured = false },
            new() { Id = 9, CourseCode = "ENG 250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Examines major authors, movements, and cultural contexts.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = 3, DepartmentName = "English", InstructorName = "Dr. Linda Torres", InstructorBio = "Dr. Torres specializes in 20th-century American fiction and has received multiple teaching excellence awards.", IsFeatured = true },
            new() { Id = 10, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions. Calculus-based approach.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", DepartmentId = 4, DepartmentName = "Physics", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is an experimental physicist whose research involves particle detectors. She is passionate about hands-on learning.", IsFeatured = false },
            new() { Id = 11, CourseCode = "PHYS 220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 3, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = 4, DepartmentName = "Physics", InstructorName = "Dr. Elena Rossi", InstructorBio = "Dr. Rossi is an experimental physicist whose research involves particle detectors. She is passionate about hands-on learning.", IsFeatured = false },
            new() { Id = 12, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of world civilizations from prehistory to 1500 CE. Covers political, social, and cultural developments across regions.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", DepartmentId = 5, DepartmentName = "History", InstructorName = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson is a historian of the ancient Mediterranean with a focus on cross-cultural exchange.", IsFeatured = false },
            new() { Id = 13, CourseCode = "HIST 275", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Examines industrialization, world wars, decolonization, and European integration.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", DepartmentId = 5, DepartmentName = "History", InstructorName = "Dr. Anna Becker", InstructorBio = "Dr. Becker is a specialist in modern German history and European political thought.", IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

