@page "/courses"

@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Course Catalog</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Course Catalog</h1>

    <form method="get" action="/courses" class="row g-3 mb-4">
        <div class="col-md-6">
            <label for="search" class="form-label">Search</label>
            <input type="text" id="search" name="search" value="@Search" class="form-control" placeholder="Search by title, code, description, or instructor…" />
        </div>
        <div class="col-md-4">
            <label for="departmentId" class="form-label">Department</label>
            <select id="departmentId" name="departmentId" class="form-select">
                <option value="">All Departments</option>
                @foreach (var dept in departments)
                {
                    <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
                }
            </select>
        </div>
        <div class="col-md-2 d-flex align-items-end">
            <button type="submit" class="btn btn-primary w-100">Filter</button>
        </div>
    </form>

    @if (courses.Count == 0)
    {
        <div class="alert alert-info">No courses match your search criteria.</div>
    }
    else
    {
        <p class="text-muted mb-3">Showing @courses.Count course(s)</p>
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead class="table-dark">
                    <tr>
                        <th>Code</th>
                        <th>Title</th>
                        <th>Department</th>
                        <th>Credits</th>
                        <th>Instructor</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var course in courses)
                    {
                        <tr>
                            <td><strong>@course.CourseCode</strong></td>
                            <td>@course.Title</td>
                            <td>@course.DepartmentName</td>
                            <td>@course.Credits</td>
                            <td>@course.InstructorName</td>
                            <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<Models.Course> courses = new();
    private List<Models.Department> departments = new();

    protected override void OnInitialized()
    {
        departments = Catalog.GetDepartments();
        courses = Catalog.SearchCourses(Search, DepartmentId);
    }
}

@page "/enroll"

@using CourseCatalog.Models
@using CourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<div class="container py-4">
    <h1 class="mb-4">Enrollment Request</h1>

    @if (submitted)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted</h4>
            <p>Thank you, <strong>@Model.FullName</strong>. Your enrollment request for
                <strong>@(selectedCourseName)</strong> has been received.</p>
            <p class="mb-0">You will receive a confirmation via your university email.</p>
        </div>
        <a href="/courses" class="btn btn-primary mt-2">Browse More Courses</a>
    }
    else
    {
        <div class="row">
            <div class="col-lg-8">
                <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                    <DataAnnotationsValidator />
                    <AntiforgeryToken />

                    <div class="mb-3">
                        <label for="fullName" class="form-label">Full Name</label>
                        <InputText id="fullName" @bind-Value="Model.FullName" class="form-control" />
                        <ValidationMessage For="() => Model.FullName" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" />
                        <ValidationMessage For="() => Model.StudentId" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                            <option value="0">— Select a course —</option>
                            @foreach (var course in allCourses)
                            {
                                <option value="@course.Id">@course.CourseCode – @course.Title (@course.Credits cr.)</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" />
                    </div>

                    <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                </EditForm>
            </div>

            <div class="col-lg-4">
                <div class="card bg-light">
                    <div class="card-body">
                        <h5 class="card-title">Instructions</h5>
                        <ul class="mb-0">
                            <li>Enter your full legal name as it appears on your student record.</li>
                            <li>Your Student ID is the 6–12 character alphanumeric code on your ID card.</li>
                            <li>Select the course you wish to enroll in from the dropdown.</li>
                            <li>You will receive a confirmation email once your request is processed.</li>
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [SupplyParameterFromForm] private EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> allCourses = new();
    private bool submitted;
    private string selectedCourseName = string.Empty;

    protected override void OnInitialized()
    {
        allCourses = Catalog.GetAllCourses();

        if (CourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = Catalog.GetCourse(Model.CourseId);
        selectedCourseName = course is not null ? $"{course.CourseCode} – {course.Title}" : "Unknown Course";
        submitted = true;
    }
}

